from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit
T0=datetime(2026,1,1,tzinfo=timezone.utc)
def p(a="100.00",s="captured"): return Payment("pay_1","inv_1",Decimal(a),status=s,created_at=T0,captured_at=T0)
# rounding
x=p(); process_refund_request(x,"49.999","u",T0); print("round",x.refunded_amount)
# full refund
x=p(); process_refund_request(x,"100.00","u",T0); print("full",x.status,x.refunded_amount)
# over refund
x=p(); process_refund_request(x,"60.00","u",T0)
try: process_refund_request(x,"50.00","u",T0)
except BillingError as e: print("over",e.code)
# non captured
try: process_refund_request(p(s="authorized"),"1.00","u",T0)
except BillingError as e: print("state",e.code)
# non positive
try: process_refund_request(p(),"0","u",T0)
except BillingError as e: print("nonpos",e.code)
# approval
try: process_refund_request(p("1000.00"),"600.00","u",T0)
except BillingError as e: print("approval",e.code)
x=p("1000.00"); process_refund_request(x,"600.00","u",T0,approved_by="mgr"); print("approved",x.refunded_amount)
print("audit",audit.events("payment_refunded")[0])
EOF"}

